public class BaseTest {
    protected WebDriver driver;
    protected WebDriverWait wait;

    @BeforeMethod
    public void setUp() {
        WebDriverManager.chromedriver().setup();
        ChromeOptions options = new ChromeOptions();
        options.addArguments("--headless", "--disable-gpu");
        driver = new ChromeDriver(options);
        wait = new WebDriverWait(driver, Duration.ofSeconds(15));
        driver.manage().window().maximize();
    }

    protected WebElement waitForElement(By locator) {
        return wait.until(ExpectedConditions.elementToBeClickable(locator));
    }

    protected void clickWithRetry(By locator, int retries) {
        for (int i = 0; i < retries; i++) {
            try {
                waitForElement(locator).click();
                return;
            } catch (StaleElementReferenceException e) {
                System.out.println("Stale element, retrying...");
            }
        }
        throw new RuntimeException("Failed to click element after " + retries + " retries");
    }

    @AfterMethod
    public void tearDown() {
        if (driver != null) {
            driver.quit();
        }
    }
}

public class UserAPITest {

    @Test
    public void testCreateUser() {
        // Positive test case
        given()
            .contentType(ContentType.JSON)
            .body("{\"name\": \"John Doe\", \"email\": \"john@example.com\"}")
        .when()
            .post("/users")
        .then()
            .statusCode(201)
            .body("id", notNullValue())
            .body("name", equalTo("John Doe"));
    }

    @Test
    public void testCreateUserInvalidEmail() {
        // Negative test case
        given()
            .contentType(ContentType.JSON)
            .body("{\"name\": \"John Doe\", \"email\": \"invalid-email\"}")
        .when()
            .post("/users")
        .then()
            .statusCode(400)
            .body("error", containsString("Invalid email"));
    }

    @Test
    public void testGetUserNotFound() {
        // Edge case
        when()
            .get("/users/99999")
        .then()
            .statusCode(404);
    }
}
